functions.tenh_pos_guard:
CREATE OR REPLACE FUNCTION public.tenh_pos_guard(p_business_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_role text; v_b jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Please sign in again.' USING ERRCODE='42501'; END IF;
  SELECT m.role::text INTO v_role
  FROM public.business_members m
  WHERE m.business_id=p_business_id AND m.user_id=auth.uid()
    AND m.is_active=true AND coalesce(m.team_password_required,false)=false
  FOR SHARE;
  IF v_role IS NULL OR NOT public.tenh_user_permission_allowed(p_business_id,auth.uid(),'pos.access') THEN
    RAISE EXCEPTION 'You do not have Point of Sale access.' USING ERRCODE='42501';
  END IF;
  IF EXISTS(
    SELECT 1 FROM public.profiles p
    WHERE p.id=auth.uid() AND coalesce((to_jsonb(p)->>'is_active')::boolean,true)=false
  ) THEN RAISE EXCEPTION 'This account has been disabled.' USING ERRCODE='42501'; END IF;
  SELECT to_jsonb(b) INTO v_b FROM public.businesses b WHERE b.id=p_business_id FOR SHARE;
  IF v_b IS NULL OR coalesce((v_b->>'is_active')::boolean,false)=false
    OR coalesce(v_b->>'subscription_status','') IN ('expired','trial_pending','trial_blocked')
    OR (nullif(v_b->>'subscription_expires_at','') IS NOT NULL AND (v_b->>'subscription_expires_at')::timestamptz<=now())
    OR (v_b->>'subscription_status'='trialing' AND nullif(v_b->>'trial_expires_at','') IS NOT NULL AND (v_b->>'trial_expires_at')::timestamptz<=now()) THEN
    RAISE EXCEPTION 'The business subscription does not allow POS sales.' USING ERRCODE='42501';
  END IF;
  RETURN v_role;
END;
$function$

functions.tenh_users_edit:
CREATE OR REPLACE FUNCTION public.tenh_users_edit(p_business uuid, p_actor uuid, p_member uuid, p_revision integer, p_operation text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; m public.business_members%rowtype; target_role text; branch uuid; msg text; name text; actor_branch uuid;
BEGIN
 r:=public.tenh_users_guard(p_business,p_actor,true);
 SELECT * INTO m FROM public.business_members WHERE id=p_member AND business_id=p_business FOR UPDATE;
 IF NOT FOUND OR m.disabled_reason='removed_by_owner' THEN RAISE EXCEPTION 'Team member was not found. Refresh User & Manage User.'; END IF;
 IF m.role='owner' OR m.user_id=p_actor THEN RAISE EXCEPTION 'You cannot modify this account.' USING ERRCODE='42501'; END IF;
 IF r<>'owner' AND m.role NOT IN ('staff','cashier') THEN RAISE EXCEPTION 'Only the business Owner can manage Manager accounts.' USING ERRCODE='42501'; END IF;
 actor_branch:=public.tenh_users_actor_branch(p_business,p_actor);
 IF actor_branch IS NOT NULL AND m.default_location_id IS DISTINCT FROM actor_branch THEN RAISE EXCEPTION 'You can manage users assigned to your branch only.' USING ERRCODE='42501'; END IF;
 IF p_revision IS NULL OR p_revision<>m.team_revision THEN RAISE EXCEPTION 'This user changed on another screen. Refresh before editing.' USING ERRCODE='40001'; END IF;
 IF p_operation='edit' THEN
  IF NOT public.tenh_user_permission_allowed(p_business,p_actor,'users.update_role') THEN RAISE EXCEPTION 'User role update permission required.' USING ERRCODE='42501'; END IF;
  target_role:=p_payload->>'role';branch:=(p_payload->>'branchId')::uuid;name:=btrim(coalesce(p_payload->>'name',''));
  IF target_role IS NULL OR target_role NOT IN ('manager','staff','cashier') OR (target_role='manager' AND r<>'owner') THEN RAISE EXCEPTION 'You cannot assign this role.' USING ERRCODE='42501'; END IF;
  IF actor_branch IS NOT NULL AND branch IS DISTINCT FROM actor_branch THEN RAISE EXCEPTION 'You can assign users to your branch only.' USING ERRCODE='42501'; END IF;
  IF length(name) NOT BETWEEN 2 AND 120 OR length(coalesce(p_payload->>'phone',''))>40 THEN RAISE EXCEPTION 'Enter valid contact details.'; END IF;
  PERFORM public.tenh_users_validate_branch(p_business,branch);
  IF (m.role IS DISTINCT FROM target_role OR m.default_location_id IS DISTINCT FROM branch) AND EXISTS(SELECT 1 FROM public.cash_register_shifts WHERE business_id=p_business AND opened_by=m.user_id AND status='open') THEN RAISE EXCEPTION 'Close this user''s open register before changing role or branch.'; END IF;
  UPDATE public.business_members SET role=target_role,default_location_id=branch,team_name=name,team_phone=btrim(coalesce(p_payload->>'phone','')),updated_at=now() WHERE id=m.id;
  UPDATE public.profiles SET role=target_role,full_name=name WHERE id=m.user_id;
  msg:='Updated team member '||name;
 ELSIF p_operation IN ('disable','remove','enable') THEN
  IF NOT public.tenh_user_permission_allowed(p_business,p_actor,'users.delete') THEN RAISE EXCEPTION 'User access management permission required.' USING ERRCODE='42501'; END IF;
  IF p_operation IN ('disable','remove') THEN
   IF EXISTS(SELECT 1 FROM public.cash_register_shifts WHERE business_id=p_business AND opened_by=m.user_id AND status='open') THEN RAISE EXCEPTION 'Close this user''s open register before disabling or removing access.'; END IF;
   IF p_operation='remove' AND p_payload->>'confirmation' IS DISTINCT FROM 'REMOVE' THEN RAISE EXCEPTION 'Type REMOVE to confirm removal of business access.'; END IF;
   UPDATE public.business_members SET is_active=false,disabled_at=now(),disabled_reason=CASE WHEN p_operation='remove' THEN 'removed_by_owner' ELSE 'manually_disabled' END,updated_at=now() WHERE id=m.id;
   msg:=CASE WHEN p_operation='remove' THEN 'Removed business access' ELSE 'Disabled business access' END;
  ELSE
   IF m.is_active OR m.disabled_reason='password_setup' THEN RAISE EXCEPTION 'This user already occupies an active or pending seat.'; END IF;
   PERFORM public.tenh_users_validate_branch(p_business,m.default_location_id);
   IF public.tenh_users_seats(p_business)>=public.tenh_users_seat_limit(p_business) THEN RAISE EXCEPTION 'No available user seats. Upgrade or disable another user.'; END IF;
   UPDATE public.business_members SET is_active=NOT team_password_required,disabled_reason=CASE WHEN team_password_required THEN 'password_setup' ELSE NULL END,disabled_at=CASE WHEN team_password_required THEN now() ELSE NULL END,updated_at=now() WHERE id=m.id;
   msg:=CASE WHEN m.team_password_required THEN 'Restored pending password setup' ELSE 'Enabled business access' END;
  END IF;
 ELSE RAISE EXCEPTION 'Invalid user action.'; END IF;
 INSERT INTO public.audit_logs(business_id,user_id,action,entity_type,entity_id,description,metadata)
 VALUES(p_business,p_actor,CASE WHEN p_operation='remove' THEN 'delete' ELSE 'update' END,'user',m.user_id,msg,jsonb_build_object('memberId',m.id,'operation',p_operation,'oldRole',m.role,'newRole',target_role,'authAccountDeleted',false));
 RETURN jsonb_build_object('memberId',m.id,'message',msg);
END;
$function$

functions.tenh_branch_visible:
CREATE OR REPLACE FUNCTION public.tenh_branch_visible(p_business uuid, p_location uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare branch uuid; h jsonb:=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb;
begin
 if auth.uid() is null or not exists(select 1 from public.business_members where business_id=p_business and user_id=auth.uid() and is_active and not coalesce(team_password_required,false)) then return false;end if;
 if nullif(h->>'x-tenh-business-id','') is not null and (h->>'x-tenh-business-id')::uuid is distinct from p_business then return false;end if;
 branch:=public.tenh_request_branch(p_business);
 return branch is null or coalesce(p_location=branch,false);
exception when insufficient_privilege or invalid_text_representation then return false;
end;$function$

functions.tenh_request_branch:
CREATE OR REPLACE FUNCTION public.tenh_request_branch(p_business uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  h jsonb:=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb;
  requested uuid;
  membership_role text;
  assigned uuid;
  header_business uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in again.' USING ERRCODE='42501';
  END IF;

  SELECT m.role::text,m.default_location_id
    INTO membership_role,assigned
  FROM public.business_members m
  WHERE m.business_id=p_business
    AND m.user_id=auth.uid()
    AND m.is_active=true
    AND coalesce(m.team_password_required,false)=false
  LIMIT 1;

  IF membership_role IS NULL THEN
    RAISE EXCEPTION 'Business access is unavailable.' USING ERRCODE='42501';
  END IF;

  IF nullif(h->>'x-tenh-business-id','') IS NOT NULL THEN
    BEGIN
      header_business:=(h->>'x-tenh-business-id')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'Invalid business context.' USING ERRCODE='42501';
    END;
    IF header_business IS DISTINCT FROM p_business THEN
      RAISE EXCEPTION 'Invalid business context.' USING ERRCODE='42501';
    END IF;
  END IF;

  IF nullif(h->>'x-tenh-branch-id','') IS NOT NULL THEN
    BEGIN
      requested:=(h->>'x-tenh-branch-id')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'Invalid operating branch.' USING ERRCODE='42501';
    END;
  END IF;

  -- Set only inside the checked online-order action; never accepted from HTTP headers.
  IF nullif(current_setting('tenh.online_order_scope',true),'') IS NOT NULL THEN
    SELECT o.location_id INTO requested FROM public.orders o
    JOIN public.business_locations l ON l.id=o.location_id AND l.business_id=o.business_id AND l.is_active AND NOT l.plan_disable_pending
    WHERE o.id=current_setting('tenh.online_order_scope')::uuid AND o.business_id=p_business AND o.order_source='online'
      AND public.tenh_receive_all_online_orders(p_business)
      AND public.tenh_user_permission_allowed(p_business,auth.uid(),'orders.view');
    IF requested IS NULL THEN RAISE EXCEPTION 'Online order access is unavailable.' USING ERRCODE='42501'; END IF;
    RETURN requested;
  END IF;

  IF membership_role='owner' THEN
    IF requested IS NULL THEN RETURN NULL; END IF;
    IF NOT EXISTS(
      SELECT 1 FROM public.business_locations l
      WHERE l.id=requested AND l.business_id=p_business AND l.is_active=true
    ) THEN
      RAISE EXCEPTION 'Invalid operating branch.' USING ERRCODE='42501';
    END IF;
    RETURN requested;
  END IF;

  IF assigned IS NULL OR NOT EXISTS(
    SELECT 1 FROM public.business_locations l
    WHERE l.id=assigned AND l.business_id=p_business AND l.is_active=true
  ) THEN
    RAISE EXCEPTION 'Your assigned branch is unavailable. Ask the Owner to assign an active branch.' USING ERRCODE='42501';
  END IF;

  IF requested IS NOT NULL AND requested IS DISTINCT FROM assigned THEN
    RAISE EXCEPTION 'This branch is not assigned to your account.' USING ERRCODE='42501';
  END IF;
  RETURN assigned;
END;
$function$

functions.record_cash_movement:
CREATE OR REPLACE FUNCTION public.record_cash_movement(p_business_id uuid, p_shift_id uuid, p_type text, p_amount numeric, p_reason text, p_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_shift public.cash_register_shifts%rowtype;
  v_id uuid;
  v_role text;
  v_branch uuid;
begin
  perform public.tenh_assert_effective_permission(p_business_id, 'register.manage');
  select bm.role::text into v_role from public.business_members bm
    where bm.business_id = p_business_id and bm.user_id = auth.uid() and bm.is_active limit 1;
  if v_role is null then raise exception 'Not authorized for this business.'; end if;
  v_branch := public.tenh_request_branch(p_business_id);
  select * into v_shift from public.cash_register_shifts
    where id = p_shift_id and business_id = p_business_id and status = 'open' for update;
  if not found then raise exception 'Open register shift not found.'; end if;
  if v_branch is null or v_shift.location_id is distinct from v_branch then
    raise exception 'This register belongs to another branch.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.business_locations where id = v_branch
    and business_id = p_business_id and is_active and not plan_disable_pending) then
    raise exception 'This branch is unavailable or waiting for its drawer to close.';
  end if;
  if v_role = 'cashier' and v_shift.opened_by <> auth.uid() then
    raise exception 'Cashiers can only change their own open register.';
  end if;
  if p_type is null or p_type not in ('cash_in', 'cash_out') then raise exception 'Invalid cash movement type.'; end if;
  if p_amount is null or p_amount::text in ('NaN', 'Infinity', '-Infinity')
    or p_amount <= 0 or p_amount > 999999999.99 or p_amount <> round(p_amount, 2) then
    raise exception 'Enter a positive amount with at most two decimal places.';
  end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then raise exception 'Reason is required.'; end if;
  insert into public.cash_movements(business_id, shift_id, location_id, created_by, movement_type, amount, reason, reference)
  values(p_business_id, p_shift_id, v_shift.location_id, auth.uid(), p_type, p_amount,
    btrim(p_reason), nullif(btrim(coalesce(p_reference, '')), '')) returning id into v_id;
  return v_id;
end;
$function$

functions.tenh_run_branch_stock:
CREATE OR REPLACE FUNCTION public.tenh_run_branch_stock(p_business uuid, p_operation text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b uuid; doc jsonb; ids uuid[]; snapshots jsonb:='[]'; r record; result jsonb; qty integer; total_after integer; wanted integer; v_purchase_id uuid; purchase_total numeric:=0; item jsonb; cost numeric;
begin
 b:=tenh_request_branch(p_business);
 if b is null then raise exception 'Choose an operating branch.'; end if;
 perform tenh_assert_plan_branch(p_business,b);
 if exists(select 1 from public.business_locations where id=b and plan_disable_pending) then raise exception 'This branch is closing after a plan change.';end if;
 if p_operation='create_purchase' then perform public.tenh_assert_effective_permission(p_business,'purchases.create');
 elsif p_operation='cancel_purchase' then perform public.tenh_assert_effective_permission(p_business,'purchases.cancel');
 elsif p_operation='receive_purchase_order' then perform public.tenh_assert_effective_permission(p_business,'purchases.update');
 elsif p_operation='cancel_order' or p_operation='reject_online' then perform public.tenh_assert_effective_permission(p_business,'orders.cancel');
 elsif p_operation='return_order' then perform public.tenh_assert_effective_permission(p_business,'orders.return');
 else raise exception 'Unsupported stock operation.'; end if;
 if p_operation='create_purchase' then
  if jsonb_typeof(p_payload->'p_items') is distinct from 'array' then raise exception 'Add purchased products.'; end if;
  for item in select value from jsonb_array_elements(p_payload->'p_items') loop
   qty:=(item->>'quantity')::integer; cost:=(item->>'unit_cost')::numeric;
   if qty is null or qty<=0 or (item->>'quantity')::numeric<>qty or cost is null or cost::text in ('NaN','Infinity','-Infinity') or cost<0 or cost<>round(cost,2) then raise exception 'Enter positive whole quantities and valid unit costs.'; end if;
   purchase_total:=purchase_total+qty*cost;
  end loop;
  select array_agg(distinct (value->>'product_id')::uuid) into ids from jsonb_array_elements(p_payload->'p_items');
  if cardinality(ids)<>jsonb_array_length(p_payload->'p_items') then raise exception 'Each product can appear only once.'; end if;
 elsif p_operation='cancel_purchase' then
  select to_jsonb(p) into doc from purchases p where id=(p_payload->>'p_purchase_id')::uuid and business_id=p_business and location_id=b for update;
  select array_agg(distinct product_id) into ids from purchase_items where purchase_id=(doc->>'id')::uuid;
 elsif p_operation='receive_purchase_order' then
  select to_jsonb(p) into doc from purchase_orders p where id=(p_payload->>'p_purchase_order_id')::uuid and business_id=p_business and location_id=b for update;
  select array_agg(distinct product_id) into ids from purchase_order_items where purchase_order_id=(doc->>'id')::uuid;
 else
  select to_jsonb(o) into doc from orders o where id=(p_payload->>'p_order_id')::uuid and business_id=p_business and location_id=b for update;
  if p_operation='reject_online' and (doc->>'order_source' not in ('online','qr') or doc->>'online_status' in ('completed','rejected')) then raise exception 'Online order cannot be rejected.'; end if;
  select array_agg(distinct product_id) into ids from order_items where order_id=(doc->>'id')::uuid;
 end if;
 if p_operation='create_purchase' then
  if exists(select 1 from unnest(ids) product_id where not exists(select 1 from public.branch_products p where p.id=product_id and p.business_id=p_business and p.is_active)) then raise exception 'Choose active products assigned to this branch.';end if;
 end if;
 if p_operation<>'create_purchase' and doc is null then raise exception 'Document not found in this branch.'; end if;
 if p_operation='return_order' then perform id from cash_register_shifts where business_id=p_business and location_id=b and status='open' for update; end if;
 if ids is null or cardinality(ids)=0 or cardinality(ids)>1000 then raise exception 'No valid products for this stock operation.'; end if;
 for r in select id,stock_quantity from products where business_id=p_business and id=any(ids) order by id for update loop
  select quantity into qty from product_location_stock where business_id=p_business and location_id=b and product_id=r.id for update;
  snapshots:=snapshots||jsonb_build_object('id',r.id,'global',r.stock_quantity,'branch',coalesce(qty,0));
 end loop;
 if jsonb_array_length(snapshots)<>cardinality(ids) then raise exception 'Product does not belong to this business.'; end if;
 case p_operation
 when 'create_purchase' then
  -- The legacy purchase overloads do not persist line items. Save the complete
  -- purchase and stock ledger here, in the same locked branch transaction.
  insert into purchases(business_id,location_id,owner_id,purchase_number,supplier_id,supplier_name,reference_number,purchase_date,notes,status,subtotal,total)
   values(p_business,b,auth.uid(),'PUR-'||upper(replace(gen_random_uuid()::text,'-','')),(p_payload->>'p_supplier_id')::uuid,
    (select name from suppliers where id=(p_payload->>'p_supplier_id')::uuid and business_id=p_business and location_id=b),
    nullif(trim(p_payload->>'p_reference_number'),''),coalesce((p_payload->>'p_purchase_date')::date,current_date),nullif(trim(p_payload->>'p_notes'),''),'received',purchase_total,purchase_total)
   returning id into v_purchase_id;
  for item in select value from jsonb_array_elements(p_payload->'p_items') loop
   qty:=(item->>'quantity')::integer; cost:=(item->>'unit_cost')::numeric;
   insert into purchase_items(owner_id,purchase_id,product_id,product_name,quantity,unit_cost,subtotal)
    select auth.uid(),v_purchase_id,id,name,qty,cost,qty*cost from public.branch_products where id=(item->>'product_id')::uuid and business_id=p_business;
   update products set stock_quantity=stock_quantity+qty,updated_at=now() where id=(item->>'product_id')::uuid and business_id=p_business returning stock_quantity into total_after;
   insert into inventory_movements(business_id,owner_id,product_id,movement_type,quantity,stock_before,stock_after,note)
    values(p_business,auth.uid(),(item->>'product_id')::uuid,'stock_in',qty,total_after-qty,total_after,'Purchase received: '||v_purchase_id::text);
  end loop;
  result:=to_jsonb(v_purchase_id);
 when 'cancel_purchase' then
  if doc->>'status' is distinct from 'received' then raise exception 'Only received purchases can be cancelled.'; end if;
  if nullif(trim(p_payload->>'p_reason'),'') is null then raise exception 'Cancellation reason is required.'; end if;
  for r in select product_id,sum(quantity)::integer quantity from purchase_items where purchase_items.purchase_id=(doc->>'id')::uuid group by product_id loop
   update products set stock_quantity=stock_quantity-r.quantity,updated_at=now() where id=r.product_id and business_id=p_business returning stock_quantity into total_after;
   insert into inventory_movements(business_id,owner_id,product_id,movement_type,quantity,stock_before,stock_after,note)
    values(p_business,auth.uid(),r.product_id,'purchase_cancelled',r.quantity,total_after+r.quantity,total_after,'Purchase cancelled: '||(doc->>'purchase_number')||'. '||(p_payload->>'p_reason'));
  end loop;
  update purchases set status='cancelled',cancellation_reason=trim(p_payload->>'p_reason'),cancelled_at=now(),updated_at=now() where id=(doc->>'id')::uuid and business_id=p_business;
 when 'receive_purchase_order' then perform public.receive_purchase_order(p_purchase_order_id=>(p_payload->>'p_purchase_order_id')::uuid,p_receipts=>p_payload->'p_receipts');
 when 'return_order' then select public.tenh_create_order_return_accounted(p_order_id=>(p_payload->>'p_order_id')::uuid,p_reason=>p_payload->>'p_reason',p_items=>p_payload->'p_items',p_refund_method=>p_payload->>'p_refund_method') into result;
 else perform public.cancel_order(p_order_id=>(p_payload->>'p_order_id')::uuid,p_reason=>p_payload->>'p_reason');
 end case;
 for r in select value as item from jsonb_array_elements(snapshots) loop
  select stock_quantity into total_after from products where id=(r.item->>'id')::uuid and business_id=p_business;
  wanted:=(r.item->>'branch')::integer+total_after-(r.item->>'global')::integer;
  if wanted<0 then raise exception 'Not enough stock in this branch. Stock in other branches cannot be used.'; end if;
  insert into product_location_stock(business_id,location_id,product_id,quantity) values(p_business,b,(r.item->>'id')::uuid,wanted)
    on conflict(location_id,product_id) do update set quantity=excluded.quantity,updated_at=now();
  if (select coalesce(sum(quantity),0) from product_location_stock where business_id=p_business and product_id=(r.item->>'id')::uuid)>total_after then raise exception 'Branch stock exceeds total stock. Reconcile inventory first.'; end if;
 end loop;
 return coalesce(result,'{}'::jsonb);
end $function$

functions.tenh_pos_catalog_scoped:
CREATE OR REPLACE FUNCTION public.tenh_pos_catalog_scoped(p_business_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; items jsonb;
begin
 result:=public.tenh_pos_catalog_scoped_before_visibility(p_business_id);
 select coalesce(jsonb_agg(item),'[]') into items from jsonb_array_elements(result->'products') item
 where exists(select 1 from public.branch_products p where p.id=(item->>'id')::uuid and p.business_id=p_business_id and p.is_pos);
 return jsonb_set(result,'{products}',items);
end;$function$

functions.adjust_branch_product_stock:
CREATE OR REPLACE FUNCTION public.adjust_branch_product_stock(p_business_id uuid, p_location_id uuid, p_product_id uuid, p_mode text, p_quantity integer, p_reason text, p_reference text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_global integer; v_before integer; v_after integer; v_delta integer;
begin
 perform public.tenh_assert_effective_permission(p_business_id,'products.stock_adjust');
 if public.tenh_request_branch(p_business_id) is distinct from p_location_id then raise exception 'This stock adjustment is outside your operating branch.' using errcode='42501'; end if;
 -- Delegate the business/role authorization and global audit to the existing RPC.
 if p_mode not in ('increase','decrease','set') or p_mode is null or p_quantity is null or p_quantity<0 or (p_mode<>'set' and p_quantity=0) then raise exception 'Invalid stock adjustment.'; end if;
 select stock_quantity into v_global from products where id=p_product_id and business_id=p_business_id for update;
 if not found then raise exception 'Product not found in this business.'; end if;
 if not exists(select 1 from business_locations where id=p_location_id and business_id=p_business_id and is_active) then raise exception 'Choose an active branch.'; end if;
 select quantity into v_before from product_location_stock where business_id=p_business_id and location_id=p_location_id and product_id=p_product_id for update;
 if (select count(*) from business_locations where business_id=p_business_id)=1 then v_before:=v_global; else v_before:=coalesce(v_before,0); end if;
 v_after:=case p_mode when 'increase' then v_before+p_quantity when 'decrease' then v_before-p_quantity else p_quantity end;
 if v_after<0 then raise exception 'Not enough stock in this branch.'; end if;
 v_delta:=v_after-v_before;
 if v_delta=0 then return; end if;
 perform set_config('tenh.adjustment_branch',p_location_id::text,true);
 perform public.adjust_product_stock(p_product_id=>p_product_id,p_mode=>case when v_delta>0 then 'increase' else 'decrease' end,p_quantity=>abs(v_delta),p_reason=>p_reason,p_reference=>p_reference);
 insert into product_location_stock(business_id,location_id,product_id,quantity) values(p_business_id,p_location_id,p_product_id,v_after) on conflict(location_id,product_id) do update set quantity=excluded.quantity,updated_at=now();
 if (select coalesce(sum(quantity),0) from product_location_stock where business_id=p_business_id and product_id=p_product_id)>(select stock_quantity from products where id=p_product_id and business_id=p_business_id) then raise exception 'Branch stock exceeds total stock. Reconcile inventory before adjusting.'; end if;
 perform set_config('tenh.adjustment_branch','',true);
end; $function$

functions.tenh_pos_checkout_registered:
CREATE OR REPLACE FUNCTION public.tenh_pos_checkout_registered(p_business_id uuid, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_existing jsonb; v_result jsonb; v_shift public.cash_register_shifts%rowtype;
  v_order public.orders%rowtype; v_branch uuid; v_request_branch uuid; v_item jsonb;
BEGIN
  PERFORM public.tenh_assert_effective_permission(p_business_id,'pos.access');
  PERFORM public.tenh_assert_effective_permission(p_business_id,'orders.create');
  IF p_input IS NULL OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid sale request.'; END IF;
  v_existing := public.tenh_pos_checkout_status(p_business_id,(p_input->>'requestId')::uuid);
  IF v_existing IS NOT NULL AND v_existing->>'orderId' IS NOT NULL THEN
    RETURN public.tenh_pos_checkout(p_business_id,p_input);
  END IF;
  v_branch := (p_input->>'branchId')::uuid;
  v_request_branch := public.tenh_request_branch(p_business_id);
  IF v_request_branch IS NULL OR v_branch IS DISTINCT FROM v_request_branch THEN
    RAISE EXCEPTION 'The operating branch changed. Review this sale in its original branch.' USING ERRCODE='42501';
  END IF;
  PERFORM public.tenh_lock_checkout_branch(p_business_id,v_branch);
  SELECT * INTO v_shift FROM public.cash_register_shifts
    WHERE business_id=p_business_id AND location_id=v_branch AND status='open' FOR UPDATE;
  IF v_shift.id IS NULL AND coalesce((select require_open_register from public.branch_pos_settings where business_id=p_business_id and location_id=v_branch),true) THEN RAISE EXCEPTION 'Open the register for this POS branch before taking payment.'; END IF;
  IF jsonb_typeof(p_input->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'items') NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'Add 1â100 items to the sale.';
  END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_input->'items') LOOP
    IF NOT EXISTS(
      SELECT 1 FROM public.products p JOIN public.product_location_stock s ON s.product_id=p.id AND s.business_id=p.business_id
      WHERE p.business_id=p_business_id AND p.id=(v_item->>'productId')::uuid AND p.is_active AND s.location_id=v_branch
        AND (p.category_id IS NULL OR EXISTS(SELECT 1 FROM public.categories c WHERE c.id=p.category_id AND c.business_id=p_business_id
          AND (c.branch_ids IS NULL OR v_branch=ANY(c.branch_ids))))
    ) THEN RAISE EXCEPTION 'A cart product or category is not assigned to this branch. Refresh POS.'; END IF;
  END LOOP;
  v_result := public.tenh_pos_checkout(p_business_id,p_input);
  SELECT * INTO v_order FROM public.orders WHERE id=(v_result->>'orderId')::uuid AND business_id=p_business_id FOR UPDATE;
  IF NOT FOUND OR v_order.location_id IS DISTINCT FROM v_branch THEN RAISE EXCEPTION 'POS order branch does not match the open register.'; END IF;
  IF v_order.register_shift_id IS NOT NULL AND v_order.register_shift_id<>v_shift.id THEN RAISE EXCEPTION 'POS order is linked to a different shift.'; END IF;
  UPDATE public.orders SET register_shift_id=v_shift.id WHERE id=v_order.id AND business_id=p_business_id;
  RETURN v_result;
END;
$function$

functions.tenh_membership_owner_lineage:
CREATE OR REPLACE FUNCTION public.tenh_membership_owner_lineage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_owner uuid;
BEGIN
  IF NEW.role='owner' THEN
    NEW.team_owner_id:=NEW.user_id;
    RETURN NEW;
  END IF;
  SELECT m.user_id INTO v_owner
  FROM public.business_members m
  WHERE m.business_id=NEW.business_id AND m.role='owner'
  ORDER BY m.created_at,m.id
  LIMIT 1;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'A workspace owner is required before adding team users.' USING ERRCODE='23514';
  END IF;
  NEW.team_owner_id:=v_owner;
  RETURN NEW;
END;
$function$

functions.tenh_users_open_register_guard:
CREATE OR REPLACE FUNCTION public.tenh_users_open_register_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_branch uuid;
BEGIN
  IF NEW.status='open' THEN
    PERFORM id FROM public.businesses WHERE id=NEW.business_id FOR UPDATE;
    IF NOT public.tenh_user_permission_allowed(NEW.business_id,NEW.opened_by,'register.manage') THEN
      RAISE EXCEPTION 'Cash Register Manage permission required.' USING ERRCODE='42501';
    END IF;
    v_branch:=public.tenh_request_branch(NEW.business_id);
    IF v_branch IS NULL OR NEW.location_id IS DISTINCT FROM v_branch THEN
      RAISE EXCEPTION 'Open the register only in your assigned operating branch.' USING ERRCODE='42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

functions.tenh_record_cash_movement_guarded:
CREATE OR REPLACE FUNCTION public.tenh_record_cash_movement_guarded(p_business_id uuid, p_shift_id uuid, p_type text, p_amount numeric, p_reason text, p_reference text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_branch uuid; v_shift_branch uuid;
BEGIN
  PERFORM public.tenh_assert_effective_permission(p_business_id,'register.manage');
  v_branch:=public.tenh_request_branch(p_business_id);
  SELECT s.location_id INTO v_shift_branch
  FROM public.cash_register_shifts s
  WHERE s.id=p_shift_id AND s.business_id=p_business_id AND s.status='open'
  FOR UPDATE;
  IF NOT FOUND OR v_branch IS NULL OR v_shift_branch IS DISTINCT FROM v_branch THEN
    RAISE EXCEPTION 'This register is not available in your assigned branch.' USING ERRCODE='42501';
  END IF;
  PERFORM public.record_cash_movement(p_business_id,p_shift_id,p_type,p_amount,p_reason,p_reference);
END;
$function$

functions.tenh_pos_catalog_scoped_before_visibilit:
CREATE OR REPLACE FUNCTION public.tenh_pos_catalog_scoped_before_visibility(p_business_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_catalog jsonb; v_branch uuid; v_products jsonb; v_categories jsonb;
  v_customers jsonb; v_stock jsonb; v_groups jsonb; v_options jsonb;
  v_branches jsonb; v_holds jsonb; v_shift jsonb;
BEGIN
  PERFORM public.tenh_assert_effective_permission(p_business_id,'pos.access');
  v_branch:=public.tenh_request_branch(p_business_id);
  v_catalog:=public.tenh_pos_catalog(p_business_id);
  IF v_branch IS NULL THEN RETURN v_catalog; END IF;

  SELECT coalesce(jsonb_agg(j),'[]'::jsonb) INTO v_products
  FROM jsonb_array_elements(coalesce(v_catalog->'products','[]'::jsonb)) j
  WHERE EXISTS(
    SELECT 1
    FROM public.branch_products p
    JOIN public.product_location_stock s
      ON s.business_id=p.business_id AND s.product_id=p.id AND s.location_id=v_branch
    WHERE p.business_id=p_business_id AND p.id=(j->>'id')::uuid AND p.is_active=true
      AND (p.category_id IS NULL OR EXISTS(
        SELECT 1 FROM public.categories c
        WHERE c.id=p.category_id AND c.business_id=p_business_id
          AND (c.branch_ids IS NULL OR v_branch=ANY(c.branch_ids))
      ))
  );

  SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name) ORDER BY c.name),'[]'::jsonb)
    INTO v_categories
  FROM public.categories c
  WHERE c.business_id=p_business_id AND (c.branch_ids IS NULL OR v_branch=ANY(c.branch_ids));

  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id',c.id,'name',c.name,'phone',c.phone,'address',to_jsonb(c)->>'address',
      'loyalty_points',c.loyalty_points
    ) ORDER BY c.name,c.id),'[]'::jsonb)
    INTO v_customers
  FROM public.customers c
  WHERE c.business_id=p_business_id AND c.location_id=v_branch;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'product_id',s.product_id,'location_id',s.location_id,'quantity',s.quantity,
      'low_stock_threshold',s.low_stock_threshold
    )),'[]'::jsonb)
    INTO v_stock
  FROM public.product_location_stock s
  WHERE s.business_id=p_business_id AND s.location_id=v_branch;

  SELECT coalesce(jsonb_agg(j),'[]'::jsonb) INTO v_groups
  FROM jsonb_array_elements(coalesce(v_catalog->'groups','[]'::jsonb)) j
  WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(v_products) p WHERE p->>'id'=j->>'product_id');

  SELECT coalesce(jsonb_agg(j),'[]'::jsonb) INTO v_options
  FROM jsonb_array_elements(coalesce(v_catalog->'options','[]'::jsonb)) j
  WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(v_products) p WHERE p->>'id'=j->>'product_id');

  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id',l.id,'name',l.name,'is_default',l.is_default,'timezone',to_jsonb(l)->>'timezone'
    ) ORDER BY l.name),'[]'::jsonb)
    INTO v_branches
  FROM public.business_locations l
  WHERE l.business_id=p_business_id AND l.id=v_branch AND l.is_active=true;

  SELECT coalesce(jsonb_agg(j),'[]'::jsonb) INTO v_holds
  FROM jsonb_array_elements(coalesce(v_catalog->'holds','[]'::jsonb)) j
  WHERE j->'draft'->>'branchId'=v_branch::text;

  SELECT jsonb_build_object('id',s.id,'location_id',s.location_id) INTO v_shift
  FROM public.cash_register_shifts s
  WHERE s.business_id=p_business_id AND s.location_id=v_branch AND s.status='open'
  ORDER BY s.opened_at DESC LIMIT 1;

  RETURN v_catalog || jsonb_build_object(
    'products',v_products,'categories',v_categories,'customers',v_customers,
    'stock',v_stock,'groups',v_groups,'options',v_options,'branches',v_branches,
    'holds',v_holds,'shift',v_shift,'defaultBranchId',v_branch::text,
    'canCreateCustomer',public.tenh_user_permission_allowed(p_business_id,auth.uid(),'customers.create')
  );
END;
$function$
